package com.bookstore.service.impl; import com.bookstore.entity.Author; import com.bookstore.exception.ResourceNotFoundException; import com.bookstore.repository.AuthorRepository; import com.bookstore.service.AuthorService; import org.springframework.stereotype.Service; import java.util.*; @Service public class AuthorServiceImpl implements AuthorService{ private final AuthorRepository repo; public AuthorServiceImpl(AuthorRepository repo){this.repo=repo;} public List<Author> findAll(){return repo.findAll();} public Author findById(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Author not found: "+id));} public Author save(Author v){return repo.save(v);} public void delete(Long id){repo.delete(findById(id));} }